<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {user,request,explain} from '../services/auth'
import {pendingRefund,startRefund,retryRefund,fundsLabel,syncLabel,releaseLabel,type RefundAction} from '../services/refunds'
import type {RefundDetail,RefundSummary,Page} from '../types/refund'
const data=ref<Page<RefundSummary>>({items:[],page:0,size:20,total:0}),selected=ref<RefundDetail|null>(null),busy=ref(false),error=ref(''),notice=ref(''),reason=ref('运营核对退款进度'),pending=ref<RefundAction|null>(null),funds=ref(''),sync=ref(''),release=ref(''),alerted=ref(false)
const id=location.pathname.split('/')[3];let sequence=0
async function load(page=data.value.page){if(!user.value||busy.value)return;const owner=user.value.userId,seq=sequence;busy.value=true;error.value='';try{if(id){const v=await request<RefundDetail>('/admin/refunds/'+encodeURIComponent(id),owner);if(seq===sequence){selected.value=v;pending.value=pendingRefund(id)}}else{const q=new URLSearchParams({page:String(page),size:'20'});if(funds.value)q.set('fundsStatus',funds.value);if(sync.value)q.set('syncStatus',sync.value);if(release.value)q.set('releaseStatus',release.value);if(alerted.value)q.set('alerted','true');const v=await request<Page<RefundSummary>>('/admin/refund-exceptions?'+q,owner);if(seq===sequence)data.value=v}}catch(e){if(seq===sequence)error.value=explain(e)}finally{if(seq===sequence)busy.value=false}}
async function control(action:'CHECK'|'RETRY'|null){if(!id||!selected.value||busy.value||!user.value||action&&!selected.value.allowedActions.includes(action))return;const seq=sequence;busy.value=true;error.value='';notice.value='';try{if(action)await startRefund(id,action,selected.value.version,reason.value);else if(pending.value)await retryRefund(pending.value);if(seq===sequence)notice.value='操作已受理；请刷新查看后台处理进度。'}catch(e){if(seq===sequence)error.value=explain(e)}finally{if(seq===sequence){pending.value=pendingRefund(id);busy.value=false;await load()}}}
watch(()=>user.value?.userId,()=>{sequence++;busy.value=false;selected.value=null;data.value={items:[],page:0,size:20,total:0};pending.value=id?pendingRefund(id):null;error.value='';notice.value='';void load()});onMounted(()=>void load());onUnmounted(()=>{sequence++})
</script>
<template><section class="operator-page"><p class="eyebrow">正经商城 · 运营工作台</p><h1>退款与库存异常</h1><p v-if="busy" role="status">正在核对退款记录…</p><p>资金退款、营销同步和库存收尾分别核对。</p><button :disabled="busy" @click="load()">刷新</button><p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><article v-if="selected"><h2>退款 {{selected.refundId}}</h2><p>订单 {{selected.orderId}} · ¥ {{selected.refundAmount}}</p><dl><dt>资金进度</dt><dd>{{fundsLabel(selected.fundsStatus)}}</dd><dt>营销同步</dt><dd>{{syncLabel(selected.syncStatus)}}</dd><dt>库存收尾</dt><dd>{{releaseLabel(selected.releaseStatus)}}</dd><dt>退款资格</dt><dd>{{selected.eligibilityStatus}}</dd><dt>当前尝试</dt><dd>{{selected.attemptId??'尚无尝试'}} · {{fundsLabel(selected.attemptStatus)}}</dd><dt>异常提示</dt><dd>{{selected.failureCode??'无'}} · 累计 {{selected.failureCount}} 次</dd><dt>后续检查</dt><dd>{{selected.nextAttemptAt?new Date(selected.nextAttemptAt).toLocaleString():'暂无计划'}} {{selected.alerted?'· 已告警':''}}</dd></dl><p>相关原因：{{selected.reasons.join('、')||'无'}}</p><details><summary>关联证据编号</summary><ul><li v-for="item in selected.evidenceIds" :key="item">{{item}}</li></ul></details><div v-if="pending"><p>原操作结果待核对：{{pending.body.operationId}}</p><button :disabled="busy" @click="control(null)">重试原操作</button></div><form v-else @submit.prevent="control('CHECK')"><label>操作原因<input v-model="reason" required maxlength="256" :disabled="busy" placeholder="例如：核对原退款结果"></label><button v-if="selected.allowedActions.includes('CHECK')" :disabled="busy||!reason.trim()">查询原退款</button><button v-if="selected.allowedActions.includes('RETRY')" type="button" :disabled="busy||!reason.trim()" @click="control('RETRY')">重试明确失败的退款</button></form><a href="/admin/refunds">返回退款列表</a></article><template v-else-if="!id"><form @submit.prevent="load(0)" class="filters"><label>资金进度<select v-model="funds"><option value="">全部</option><option v-for="s in ['NONE','PENDING','UNKNOWN','FAILED','SUCCEEDED']" :key="s" :value="s">{{fundsLabel(s)}}</option></select></label><label>营销同步<select v-model="sync"><option value="">全部</option><option v-for="s in ['NOT_CREATED','PENDING','WAITING_DEPENDENCY','ACCEPTED','REVIEW_REQUIRED']" :key="s" :value="s">{{syncLabel(s)}}</option></select></label><label>库存收尾<select v-model="release"><option value="">全部</option><option v-for="s in ['HELD','READY','RELEASED','ALREADY_RELEASED','REVIEW_REQUIRED']" :key="s" :value="s">{{releaseLabel(s)}}</option></select></label><label><input v-model="alerted" type="checkbox">仅告警</label><button :disabled="busy">筛选</button></form><p v-if="!data.items.length&&!busy&&!error">暂无匹配退款。</p><article v-for="item in data.items" :key="item.refundId"><h2><a :href="'/admin/refunds/'+item.refundId">退款 {{item.refundId}}</a></h2><p>订单 {{item.orderId}} · ¥ {{item.refundAmount}}</p><p>{{fundsLabel(item.fundsStatus)}} · {{syncLabel(item.syncStatus)}} · {{releaseLabel(item.releaseStatus)}}</p></article><button :disabled="busy||data.page===0" @click="load(data.page-1)">上一页</button><span>第 {{data.page+1}} 页 · 共 {{data.total}} 条</span><button :disabled="busy||(data.page+1)*data.size>=data.total" @click="load(data.page+1)">下一页</button></template></section></template>
<style scoped>article{overflow-wrap:anywhere}dl{display:grid;grid-template-columns:7em 1fr;gap:.7em}dd{margin:0}.filters{display:flex;flex-wrap:wrap;gap:1em}.filters label{display:flex;flex-direction:column}input,select{max-width:100%}@media(max-width:600px){dl{grid-template-columns:1fr}.filters{flex-direction:column}h2{font-size:1.1rem}}</style>
